#!/usr/bin/env python3

"""
Test script to reproduce the pdftk issue on Ubuntu systems
"""

import subprocess
import sys
import os

# Add the current directory to the path so we can import paper2remarkable modules
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

def test_check_pdftool_logic():
    """Test the current check_pdftool logic"""
    from paper2remarkable.utils import check_pdftool

    print("Testing check_pdftool logic...")

    # Test 1: What happens when pdftk is not available but qpdf is
    try:
        result = check_pdftool("nonexistent_pdftk", "qpdf")
        print(f"Test 1 - pdftk nonexistent, qpdf available: {result}")
    except Exception as e:
        print(f"Test 1 FAILED: {e}")

    # Test 2: What happens when both are available
    try:
        result = check_pdftool("pdftk", "qpdf")
        print(f"Test 2 - both available: {result}")
    except Exception as e:
        print(f"Test 2 FAILED: {e}")

    # Test 3: What happens when neither is available
    try:
        result = check_pdftool("nonexistent_pdftk", "nonexistent_qpdf")
        print(f"Test 3 - neither available: {result}")
    except Exception as e:
        print(f"Test 3 FAILED (expected): {e}")

def test_direct_subprocess_call():
    """Test what happens with direct subprocess call to nonexistent pdftk"""
    print("\nTesting direct subprocess call...")
    try:
        status = subprocess.call(["nonexistent_pdftk"])
        print(f"Direct call status: {status}")
    except FileNotFoundError as e:
        print(f"Direct call FileNotFoundError: {e}")
    except Exception as e:
        print(f"Direct call other error: {e}")

def test_actual_pdftk_and_qpdf():
    """Test what pdftk and qpdf actually return"""
    print("\nTesting actual tools...")

    # Test pdftk
    try:
        status = subprocess.call(["pdftk"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        print(f"pdftk status: {status}")
    except FileNotFoundError as e:
        print(f"pdftk FileNotFoundError: {e}")
    except Exception as e:
        print(f"pdftk other error: {e}")

    # Test qpdf
    try:
        status = subprocess.call(["qpdf", "--help"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        print(f"qpdf status: {status}")
    except FileNotFoundError as e:
        print(f"qpdf FileNotFoundError: {e}")
    except Exception as e:
        print(f"qpdf other error: {e}")

if __name__ == "__main__":
    print("=== Testing pdftk/qpdf issue reproduction ===")
    test_actual_pdftk_and_qpdf()
    test_direct_subprocess_call()
    test_check_pdftool_logic()

